import pandas as pd


def run(inputs: dict) -> dict:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # 1. Deduplicate events delivered more than once (distinct by seq)
    cdc_events = cdc_events.drop_duplicates(subset=["seq"], keep="first")

    # Snapshot of the ORIGINAL target_state for the replay guard
    orig_last_seq = dict(zip(target_state["order_id"], target_state["last_seq"]))
    orig_exists = set(target_state["order_id"])

    # Working state initialized from target_state
    working = {}
    for _, row in target_state.iterrows():
        working[row["order_id"]] = {
            "status": row["status"],
            "amount": row["amount"],
            "last_seq": row["last_seq"],
            "exists": True,
        }

    # 2. Replay guard: skip events for orders that already have a row with
    #    last_seq >= event seq (guard uses the ORIGINAL target_state only).
    def guard_ok(row):
        oid = row["order_id"]
        if oid in orig_exists:
            return row["seq"] > orig_last_seq[oid]
        return True

    if len(cdc_events) > 0:
        mask = cdc_events.apply(guard_ok, axis=1)
        cdc_events = cdc_events[mask]

    # 3. Apply remaining events strictly in seq order (the only trusted order)
    cdc_events = cdc_events.sort_values("seq", kind="mergesort")

    for _, ev in cdc_events.iterrows():
        oid = ev["order_id"]
        op = ev["op"]
        seq = ev["seq"]
        status = ev["status"]
        amount = ev["amount"]

        if op in ("I", "U"):
            if oid in working and working[oid]["exists"]:
                cur = working[oid]
                if op == "U" and pd.isna(amount):
                    new_amount = cur["amount"]
                else:
                    new_amount = amount
                cur["status"] = status
                cur["amount"] = new_amount
                cur["last_seq"] = seq
                cur["exists"] = True
            else:
                working[oid] = {
                    "status": status,
                    "amount": amount,
                    "last_seq": seq,
                    "exists": True,
                }
        elif op == "D":
            if oid in working and working[oid]["exists"]:
                working[oid]["exists"] = False
                working[oid]["last_seq"] = seq
            # 'D' for a missing (or already-deleted) order does nothing.

    # 4 & 5. Build outputs
    new_state_rows = []
    tombstone_rows = []
    for oid, st in working.items():
        if st["exists"]:
            new_state_rows.append(
                {
                    "order_id": oid,
                    "status": st["status"],
                    "amount": st["amount"],
                    "last_seq": st["last_seq"],
                }
            )
        else:
            tombstone_rows.append(
                {
                    "order_id": oid,
                    "deleted_seq": st["last_seq"],
                }
            )

    new_state = pd.DataFrame(
        new_state_rows, columns=["order_id", "status", "amount", "last_seq"]
    )
    tombstones = pd.DataFrame(
        tombstone_rows, columns=["order_id", "deleted_seq"]
    )

    if len(new_state) > 0:
        new_state["order_id"] = new_state["order_id"].astype("int64")
        new_state["last_seq"] = new_state["last_seq"].astype("int64")
        new_state["amount"] = new_state["amount"].astype("float64")
    else:
        new_state = pd.DataFrame(
            {
                "order_id": pd.Series(dtype="int64"),
                "status": pd.Series(dtype="object"),
                "amount": pd.Series(dtype="float64"),
                "last_seq": pd.Series(dtype="int64"),
            }
        )

    if len(tombstones) > 0:
        tombstones["order_id"] = tombstones["order_id"].astype("int64")
        tombstones["deleted_seq"] = tombstones["deleted_seq"].astype("int64")
    else:
        tombstones = pd.DataFrame(
            {
                "order_id": pd.Series(dtype="int64"),
                "deleted_seq": pd.Series(dtype="int64"),
            }
        )

    return {"new_state": new_state, "tombstones": tombstones}
